    function hpRiskCoverageCard(x) {
        const r = getRace(x.race), p = r?.poolIntelligence || {}, buckets = [ hpPoolBucketHtml("Base", p.base, r), hpPoolBucketHtml("Defensa", p.defense, r), hpPoolBucketHtml("Cobertura", p.coverage, r), hpPoolBucketHtml("Primer corte", p.firstCut, r), hpPoolBucketHtml("Outsider", p.outsiders, r) ].filter(Boolean).join(""), note = hpCleanFinalRiskNote(x.note || r?.generalRead || "", x.race);
        return `<div class="final-risk-card"><div class="final-risk-head"><div><div class="final-risk-race">R${x.race}</div><div class="final-risk-status">${esc(decisionEs(x.status || r?.decision?.officialDecision || "—"))}</div></div><div class="final-risk-gap">+${Number(x.gap ?? r?.decision?.gap ?? 0).toFixed(1)}</div></div>${buckets ? `<div class="final-risk-buckets">${buckets}</div>` : '<div class="final-risk-empty">Sin cobertura adicional estructurada.</div>'}${note ? `<div class="final-risk-note">${esc(note)}</div>` : ""}</div>`;
    }
